object Solution {
  def suggestedProducts(products: Array[String], searchWord: String): List[List[String]] = {
    val sortedProducts = products.sorted
    var result = List[List[String]]()
    var prefix = ""
    for (ch <- searchWord) {
      prefix += ch
      // Binary search to find the first product >= prefix
      val start = lowerBound(sortedProducts, prefix)
      val suggestions = scala.collection.mutable.ListBuffer[String]()
      var i = start
      while (i < sortedProducts.length && suggestions.size < 3) {
        if (sortedProducts(i).startsWith(prefix)) suggestions += sortedProducts(i)
        else i = sortedProducts.length // break loop
        i += 1
      }
      result ::= suggestions.toList
    }
    result.reverse
  }

  // Find the first index where product >= prefix
  private def lowerBound(arr: Array[String], prefix: String): Int = {
    var left = 0
    var right = arr.length
    while (left < right) {
      val mid = left + (right - left) / 2
      if (arr(mid) >= prefix) right = mid
      else left = mid + 1
    }
    left
  }
